package com.game_manager.gm.workflow; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*; import com.game_manager.gm.notification.*; import io.micrometer.core.instrument.simple.SimpleMeterRegistry; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class WorkflowSlaWorkerTest {@Test void reminderAndEscalationAreDeterministicWithFixedClock(){Instant now=Instant.parse("2026-03-29T01:30:00Z");WorkflowStepRepository repository=mock(WorkflowStepRepository.class);WorkflowService service=mock(WorkflowService.class);WorkflowNotificationGateway notices=mock(WorkflowNotificationGateway.class);WorkflowDefinitionVersion version=new WorkflowDefinitionVersion();WorkflowInstance instance=new WorkflowInstance();instance.setDefinitionVersion(version);instance.setTitle("DST expense");WorkflowStep step=new WorkflowStep();step.setId(UUID.randomUUID());step.setInstance(instance);step.setStepKey("MANAGER");step.setAssigneeRole("ADMIN");step.setStatus(StepStatus.ACTIVE);step.setReminderAt(now.minusSeconds(1));step.setDueAt(now.minusSeconds(1));when(repository.findByStatusAndReminderAtBeforeAndRemindedAtIsNull(StepStatus.ACTIVE,now)).thenReturn(List.of(step));when(repository.findByStatusAndDueAtBefore(StepStatus.ACTIVE,now)).thenReturn(List.of(step));when(service.recipients(step)).thenReturn(List.of(UUID.randomUUID()));when(service.schema(version)).thenReturn(new WorkflowSchema("MANAGER",List.of(new WorkflowSchema.Step("MANAGER","Manager","ADMIN",24,12,"OWNER")),List.of()));new WorkflowSlaWorker(repository,service,notices,Clock.fixed(now,ZoneOffset.UTC),new SimpleMeterRegistry()).process();assertThat(step.getRemindedAt()).isEqualTo(now);assertThat(step.getAssigneeRole()).isEqualTo("OWNER");assertThat(instance.isEscalated()).isTrue();verify(notices,times(2)).send(eq(step.getId()),any(),any(),anyString(),eq("DST expense"));}}
